from typing import List

def largest_subset(arr: List[int], n: int) -> int:
    arr.sort()
    dp = [1] * len(arr)
    for i in range(1, len(arr)):
        for j in range(i):
            if (arr[i] % arr[j] == 0 and
                dp[i] < dp[j] + 1):
                dp[i] = dp[j] + 1

    return max(dp)

